/bin/bash -lc "OPENBLAS_NUM_THREADS=4 python - <<'PY'
import gzip,pandas as pd,numpy as np
from scipy.io import mmread
g=pd.read_csv('differential.composition.q1.genes.txt.gz',sep='\\t').gene_symbols.astype(str).to_numpy(); d={x:i for i,x in enumerate(g)}
with gzip.open('differential.composition.q1.1.mtx.gz','rb') as f:a=mmread(f).tocsr().T
with gzip.open('differential.composition.q1.2.mtx.gz','rb') as f:b=mmread(f).tocsr().T
M={
'astrocyte':['GFAP','AQP4','ALDH1L1','SLC1A2'],'microglial cell':['P2RY12','TMEM119','C1QA','C1QB','C1QC'],'RPE cell':['RPE65','BEST1','PMEL','TYR','TTR'],'cone cell':['ARR3','GNAT2','OPN1LW','OPN1MW','OPN1SW','PDE6H'],'rod cell':['RHO','GNAT1','NRL','PDE6A','PDE6B','SAG'],'horizontal cell':['ONECUT1','ONECUT2','PROX1','CALB1','LHX1'],'bipolar cell':['VSX2','TRPM1','PCP2','PRKCA','GRM6','CABP5'],'RGC':['RBPMS','SNCG','POU4F1','POU4F2','NEFL','NEFM'],'T cells':['CD3D','CD3E','TRAC','IL7R','CD247'],'macrophage':['LYZ','CD68','FCGR3A','MSR1','MRC1'],'Schwann cell':['MPZ','SOX10','S100B','PLP1','MBP','PMP22'],'Pericyte':['RGS5','PDGFRB','CSPG4','MCAM','DES','ACTA2'],'B cell':['CD79A','MS4A1','CD37','CD74','CD22','CD19'],'fibroblast':['COL1A1','COL1A2','DCN','LUM','COL3A1','PDGFRA'],'endothelial cell':['PECAM1','VWF','CLDN5','EMCN','KDR','RAMP2'],'muller glia cell':['RLBP1','GLUL','SLC1A3','APOE','VIM','CLU']}
for ct,gs in M.items():
 j=[d[z] for z in gs]; out=[]
 for x in [a,b]:
  n=np.asarray((x[:,j]>0).sum(1)).ravel(); out.append('/'.join(str(int((n>=q).sum())) for q in [1,2,3]))
 print(f'{ct:18s} {out[0]:>15s} {out[1]:>15s}')
PY"
